let LANG = 'en';

function pickLanguage(saved) {
  if (saved && I18N[saved]) return saved;
  for (const l of navigator.languages || [navigator.language || 'en']) {
    const base = String(l).toLowerCase().split('-')[0];
    if (I18N[base]) return base;
  }
  return 'en';
}

const pluralRulesCache = {};
function t(key, vars = {}) {
  let v = I18N[LANG]?.[key] ?? I18N.en[key] ?? key;
  if (v && typeof v === 'object' && !Array.isArray(v)) {
    const rules = pluralRulesCache[LANG] || (pluralRulesCache[LANG] = new Intl.PluralRules(LANG));
    v = v[rules.select(Number(vars.n) || 0)] ?? v.other;
  }
  return String(v).replace(/\{(\w+)\}/g, (m, k) => {
    if (!(k in vars)) return m;
    return typeof vars[k] === 'number' ? vars[k].toLocaleString(LANG) : String(vars[k]);
  });
}

const catName = (c) => t('cat.' + c);

// Fills every [data-i18n*] element in the page.
function applyI18nDom(root = document) {
  root.querySelectorAll('[data-i18n]').forEach((el) => {
    const n = el.dataset.i18nN;
    el.textContent = t(el.dataset.i18n, n !== undefined ? { n: Number(n) } : {});
  });
  root.querySelectorAll('[data-i18n-html]').forEach((el) => { el.innerHTML = t(el.dataset.i18nHtml); }); // our own trusted strings only
  root.querySelectorAll('[data-i18n-ph]').forEach((el) => { el.placeholder = t(el.dataset.i18nPh); });
  root.querySelectorAll('[data-i18n-aria]').forEach((el) => { el.setAttribute('aria-label', t(el.dataset.i18nAria)); });
}
